package cli

// cfgDefaultTemplate is Python config.generate_default_config's text, word for
// word. {HOME}, {MEMDB}, {PROJ_LINE} and {SCOPE_LINE} are filled in; {BT} is
// a backtick (a Go raw string cannot hold one).
const cfgDefaultTemplate = `# Remedy AI Configuration
# Generated by remedy config init
# Owner's manual (desktop F1) and LICENSE (Apache-2.0) describe the terms.

name = "Remedy"
# Partner presentation: female (default) | male | neutral
agent_gender = "female"
# What your partner calls you (desktop Settings → You & Agent)
# user_name = "You"
# Owner language: auto (match OS + what they type) or a BCP-47 id (es, ja, …)
# ui_language = "auto"
persona = "default"
home_dir = "{HOME}"

# First-run setup: false until {BT}remedy setup{BT} / desktop wizard / --skip-setup
setup_completed = false

# Optional default folder (Settings). New Session does NOT auto-attach a project —
# sessions without a project are root (full access). Pick a project per session
# or set a default here for tools that need a workspace root.
{PROJ_LINE}
{SCOPE_LINE}

# --- LLM Provider ---
# Supported: openai, anthropic, google, deepseek, xai, groq, mistral, openrouter, ollama, custom
# xAI also supports OAuth (Sign in with xAI) via desktop Settings / {BT}remedy auth login xai{BT}
llm_provider = "openai"
# llm_model: leave unset to use the provider's own default from its models list.
llm_base_url = "https://api.openai.com/v1"
# llm_api_key - prefer secure store (desktop Settings) or REMEDY_LLM_API_KEY env:
# llm_api_key = "sk-..."
# XAI_API_KEY auto-selects xAI on first run when present

# Sleev (https://sleev.ai) — local gateway that compresses agent context before
# it hits your provider. Same keys/models; saves tokens on long sessions.
# Install: npm install -g sleev && sleev  (gateway default http://127.0.0.1:17321)
# sleev_enabled = false
# sleev_gateway_url = ""   # empty = auto-discover from Sleev install
# sleev_allow_remote_gateway = false  # true only for LAN/remote gateway (API keys leave machine)

# Search paths for bundled + user skills
skills_dir = []

# SQLite memory database
memory_db_path = "{MEMDB}"

# Soft cap for skills in the hot catalog (Settings → Provider catalog)
# skills_active_budget = 80

# Messaging channels (also Settings → Messengers). Tokens live in the secure store.
# Desktop sessions share the same memory.db — messenger chats appear in the sidebar.
# cli, telegram, discord, slack, mattermost, whatsapp, teams, matrix, google_chat, signal, web, api
enabled_channels = ["cli"]

# MCP *client* server list (advanced). Desktop also exposes Remedy as MCP *host*.
mcp_servers = []

# Learning loop / partner skills
allow_skill_creation = true
auto_approve_threshold = 0.8

# Logging: DEBUG | INFO | WARNING | ERROR
log_level = "INFO"

# Optional tone flag (Settings → Advanced); default off
sarcasm_mode = false

# Claimidx (Settings → Privacy). Set true to install and run the local
# Claimidx host (downloaded from PyPI), false to stop it. Left unset, a host
# that is already installed keeps running and nothing new is downloaded.
# claimidx_enabled = false

# Claimidx public ledger submits (Settings → Advanced); default off: claims
# stay on this computer. Set true to share them with the public ledger.
claimidx_public_ledger = false

# --- Partner controls (also on status bar / Settings → Security & power) ---
# approval_mode = "auto"    # ask | auto (in-project) | full (warn, jail off except auth)
# trust_profile = "balanced"  # conservative | balanced | autonomous (mail/pay never skipped)
# thinking_level = "high"   # off | low | medium | high
# --- Reasoning and context (unset = each provider's default) ---
# reasoning_effort = "medium"       # none | minimal | low | medium | high | xhigh
# thinking_budget_tokens = 8000     # Anthropic budget thinking / Gemini thinking budget (1024-128000)
# max_output_tokens = 8192          # per-round output ceiling (256-256000)
# context_window_tokens = 128000    # history window used for truncation (4096-2000000)
# [model_settings."o3"]             # per-model override ("<provider>/<model>" also works)
# reasoning_effort = "high"
# tool_process = "off"      # off | medium | full
# web_tools_enabled = true  # public web_fetch + web_search (SSRF-guarded); set false to disable
# web_respect_robots = true # obey robots.txt on fetched pages; false = owner override
# web_search_url = "http://127.0.0.1:8080"  # optional: your own SearXNG (needs json in search.formats)
# web_search_url_allow_private = true       # required for a loopback/LAN instance you run (SSRF override)
# First-run downloads OpenSERP (~10 MB) to ~/.remedy/bin and binds it to 127.0.0.1:17410.
# http_bootstrap — omit for auto: False on desktop sidecar, True on plain serve.
# http_bootstrap = true     # browser loopback token; desktop prefers IPC

# Maturity gates (experimental / advanced organs — default off / honest)
# soul_field_enabled = true    # personhood / Soul Field (default on; set false to opt out)
# build_os_advanced = false    # Build OS frontiers A–H tools
# rmb_enabled = true           # RMB local agent host allowed when configured

# Retention (days; 0 = never auto-purge). Soft defaults: shots 14d, undo/logs 30d
# retention_session_days = 0
# retention_attachment_days = 0
# retention_computer_shot_days = 14
# retention_undo_days = 30
# retention_log_days = 30
# memory_encrypt = false       # SQLCipher when a cipher-linked sqlite is installed

# Organism / token-budget knobs (Settings → Advanced; omit to keep defaults).
# Also: REMEDY_NO_VOICE_EVOLUTION=1, REMEDY_REACT_MAX_RESULT_CHARS, and
# [self_inject] idle_seconds still work and map onto these keys.
# [advanced]
# improve_tick_s = 60
# improve_tick_min_s = 20
# improve_tick_max_s = 900
# improve_heavy_window_s = 300
# turn_end_timeout_s = 30
# after_tool_batch_timeout_s = 10
# pulse_learn_timeout_s = 45
# soul_inject_chars = 1400
# max_result_chars = 30000
# soul_max_bytes = 65536
# residue_max_bytes = 262144
# journal_max_bytes = 65536
# learn_log_max_bytes = 262144
# learn_log_max_lines = 400
# max_episodes = 12
# max_future_dreams = 8
# max_phenotypes = 128
# episode_recent_protect = 4
# episode_halflife_days = 30.0
# max_tensions = 16
# max_self_lessons = 24
# max_voice_markers = 12
# max_open_threads = 10
# vigil_offer_turns = 12
# dream_cooldown_s = 120
# organism_compact_every_s = 86400
# organism_stall_after_s = 604800
# voice_evolution = true
# self_inject_idle_s = 300
# drives_enabled = true
# drive_drift_rate = 0.04
# proactive_reach_out = false
# reach_out_threshold = 0.85
# reach_out_min_interval_s = 604800
# autobiography_chars = 400
# affect_enabled = true
# affect_tone_weight = 0.15
# voice_drift_from_affect = true
# outcome_learning = true
# weekly_reflection = true
# weekly_reflection_s = 604800
# inner_language = true
# inner_language_verbosity = "dense"
# inner_coinage = true
# inner_coinage_rate = 0.3
# inner_lexicon_cap = 128
# inner_audit = true
# onboarding = true
# onboarding_reask = false
# house_rules_permission = "confirm_sensitive"
# house_rules_audit = true

# Memory harness (chat compression)
# harness_mode = "auto"     # auto | off (keep a long conversation inside the model window)
# harness_min_context_pct = 0.75
# harness_max_context_pct = 0.92

# Desktop always-ready (also in Settings / desktop.json)
# update_check = "auto"   # auto (check in-app, tell you) | ask (only when you check)
# launch_at_login = false
# start_in_tray = false
# close_to_tray = true

# In-app Browser slide homepage (Settings → Project workspace)
# browser_home_url = "https://github.com/AhmiDarrow/RemedyAI"

[gateway]
heartbeat_interval = 60
rate_limit = 120

[execution]
default_timeout = 30
max_retries = 3
retry_backoff = 1.0

# Messengers — non-secret fields only (bot tokens via Settings / secret store)
[telegram]
allow_chat_ids = []
allow_all = false

[discord]
channel_id = ""
guild_id = ""

[slack]
channel_id = ""

[mattermost]
base_url = ""
team_id = ""
channel_id = ""

[whatsapp]
phone_number_id = ""
allow_from = []

[teams]
app_id = ""
tenant_id = ""

[matrix]
homeserver = ""
user_id = ""
room_id = ""

[google_chat]
space_id = ""

[signal]
cli_path = "signal-cli"
account = ""

# Local visual decoder (llama-server + SmolVLM2 2.2B) — first-run download; not in installer
[vision]
enabled = false
model_id = "smolvlm2-2.2b"
# Prefer local image→text even when the chat model has native vision (saves provider tokens)
force_decode = false
host = "127.0.0.1"
port = 8740
auto_start = true
idle_stop_s = 600
`
